/**
 * modelCtx.js — 当前编辑主模型的响应式上下文
 *
 * 保存当前模型 key，并暴露该模型的 buildModelContext 结果（catalog / MODEL_ORIG /
 * MODEL_INFO / url 等）。切换模型：先 setModel(key)（会重算 ctx 快照），再由外层
 * 以 :key="ctx.key" 重挂载 Viewer3D / RightPanel 等（组件在 setup 时读取 ctx.current，
 * 确保拿到的是新模型数据）。
 */
import { reactive, computed } from 'vue'
import { buildModelContext, DEFAULT_MODEL } from './catalog'

export const modelCtx = reactive({
  key: DEFAULT_MODEL
})

const ctxCache = {}
export function getCtx() {
  const k = modelCtx.key
  if (!ctxCache[k]) ctxCache[k] = buildModelContext(k)
  return ctxCache[k]
}

/** 当前模型完整上下文（同步快照对象；配合外层重挂载使用） */
export const current = computed(() => getCtx())

/** 切换模型并返回新上下文（调用方随后应触发重挂载） */
export function setModel(key) {
  if (!key || key === modelCtx.key) return getCtx()
  modelCtx.key = String(key)
  return getCtx()
}

/** 模板友好：catalog 本体 */
export const currentCatalog = computed(() => current.value.catalog)
export const currentInfo = computed(() => current.value.MODEL_INFO)
